    # Common TLDs for strict validation (subset - in production, use complete list)
    VALID_TLDS = frozenset([
        'com', 'org', 'net', 'edu', 'gov', 'mil', 'int', 'arpa',
        'co', 'uk', 'de', 'fr', 'jp', 'au', 'ca', 'io', 'ai'
    ])

    # Precompiled regex patterns for performance
    _PATTERNS = {
        'consecutive_dots': re.compile(r'\.\.'),
        'valid_local_chars': re.compile(r'^[a-zA-Z0-9._+-]+$'),
        'valid_domain_chars': re.compile(r'^[a-zA-Z0-9.-]+$'),
        'valid_label_chars': re.compile(r'^[a-zA-Z0-9-]+$'),
        'tld_pattern': re.compile(r'^[a-zA-Z]{2,}$'),
        # Looser pattern for basic validation
        'basic_email': re.compile(r'^[^@\s]+@[^@\s]+\.[^@\s]+$')
    }

    def __init__(self, validation_level: ValidationLevel = ValidationLevel.STANDARD):
        """
        Initialize validator with specified validation level.

        Args:
            validation_level: How strict the validation should be
        """
        self.validation_level = validation_level
        self._cache_info = {'hits': 0, 'misses': 0, 'size': 0}

    @lru_cache(maxsize=1000)
    def validate(self, email: str) -> ValidationResult:
        """
        Main validation method with caching.

        Args:
            email: Email address to validate

        Returns:
            ValidationResult with detailed feedback
        """
        self._cache_info['size'] = len(self.validate.cache_info())

        # Input validation
        if not isinstance(email, str):
            return ValidationResult(
                False, 
                "INVALID_TYPE", 
                f"Expected string, got {type(email).__name__}"
            )

        email = email.strip()
        if not email:
            return ValidationResult(False, "EMPTY_EMAIL", "Email cannot be empty")

        # Choose validation method based on level
        if self.validation_level == ValidationLevel.BASIC:
            return self._validate_basic(email)
        elif self.validation_level == ValidationLevel.STANDARD:
            return self._validate_standard(email)
        else:  # STRICT
            return self._validate_strict(email)

    def _validate_basic(self, email: str) -> ValidationResult:
        """Basic regex-based validation for performance."""
        if len(email) > self.MAX_EMAIL_LENGTH:
            return ValidationResult(False, "TOO_LONG", "Email exceeds maximum length")

        if not self._PATTERNS['basic_email'].match(email):
            return ValidationResult(False, "INVALID_FORMAT", "Invalid email format")

        return ValidationResult(True)

    def _validate_standard(self, email: str) -> ValidationResult:
        """Standard validation with comprehensive checks."""
        # Length check
        if len(email) > self.MAX_EMAIL_LENGTH:
            return ValidationResult(False, "TOO_LONG", "Email exceeds maximum length")

        # Whitespace check
        if any(char.isspace() for char in email):
            return ValidationResult(False, "CONTAINS_WHITESPACE", "Email cannot contain whitespace")

        # @ symbol check
        at_count = email.count('@')
        if at_count != 1:
            error_code = "MISSING_AT" if at_count == 0 else "MULTIPLE_AT"
            return ValidationResult(False, error_code, f"Email must contain exactly one @ symbol, found {at_count}")

        # Split and validate parts
        local_part, domain_part = email.split('@', 1)

        # Validate local part
        local_result = self._validate_local_part(local_part)
        if not local_result.is_valid:
            return local_result

        # Validate domain part
        domain_result = self._validate_domain_part(domain_part)
        if not domain_result.is_valid:
            return domain_result

        # Combine warnings
        warnings = local_result.warnings + domain_result.warnings
        return ValidationResult(True, warnings=warnings)

    def _validate_strict(self, email: str) -> ValidationResult:
        """Strict validation with additional RFC compliance checks."""
        # First run standard validation
        result = self._validate_standard(email)
        if not result.is_valid:
            return result

        local_part, domain_part = email.split('@', 1)
        warnings = result.warnings.copy()

        # Additional strict checks
        # Check for quoted strings (not commonly used)
        if '"' in local_part:
            warnings.append("Quoted strings in local part are discouraged")

        # Check TLD against known valid TLDs
        labels = domain_part.split('.')
        tld = labels[-1].lower()
        if tld not in self.VALID_TLDS:
            warnings.append(f"TLD '{tld}' is not in common TLD list")

        # Check for suspicious patterns
        if local_part.count('.') > 3:
            warnings.append("Excessive dots in local part")

        if any(label.isdigit() for label in labels[:-1]):  # Numeric domains (except IP)
            warnings.append("Numeric domain labels detected")

        return ValidationResult(True, warnings=warnings)

    def _validate_local_part(self, local_part: str) -> ValidationResult:
        """Validate the local part (before @) with detailed error reporting."""
        if not local_part:
            return ValidationResult(False, "EMPTY_LOCAL", "Local part cannot be empty")

        if len(local_part) > self.MAX_LOCAL_LENGTH:
            return ValidationResult(False, "LOCAL_TOO_LONG", f"Local part exceeds {self.MAX_LOCAL_LENGTH} characters")

        # Boundary checks
        if local_part.startswith('.') or local_part.endswith('.'):
            return ValidationResult(False, "LOCAL_BOUNDARY_DOT", "Local part cannot start or end with dot")

        # Consecutive dots
        if self._PATTERNS['consecutive_dots'].search(local_part):
            return ValidationResult(False, "LOCAL_CONSECUTIVE_DOTS", "Local part cannot contain consecutive dots")

        # Character validation
        if not self._PATTERNS['valid_local_chars'].match(local_part):
            return ValidationResult(False, "LOCAL_INVALID_CHARS", "Local part contains invalid characters")

        warnings = []
        # Warning for potentially problematic patterns
        if local_part.startswith('+'):
            warnings.append("Local part starting with + may not be universally supported")

        return ValidationResult(True, warnings=warnings)

    def _validate_domain_part(self, domain_part: str) -> ValidationResult:
        """Validate the domain part (after @) with detailed error reporting."""
        if not domain_part:
            return ValidationResult(False, "EMPTY_DOMAIN", "Domain part cannot be empty")

        if len(domain_part) > self.MAX_DOMAIN_LENGTH:
            return ValidationResult(False, "DOMAIN_TOO_LONG", f"Domain part exceeds {self.MAX_DOMAIN_LENGTH} characters")

        # Must contain at least one dot
        if '.' not in domain_part:
            return ValidationResult(False, "NO_TLD", "Domain must contain at least one dot")

        # Boundary checks
        if domain_part.startswith('.') or domain_part.endswith('.') or \
           domain_part.startswith('-') or domain_part.endswith('-'):
            return ValidationResult(False, "DOMAIN_BOUNDARY", "Domain cannot start/end with dot or hyphen")

        # Consecutive dots
        if self._PATTERNS['consecutive_dots'].search(domain_part):
            return ValidationResult(False, "DOMAIN_CONSECUTIVE_DOTS", "Domain cannot contain consecutive dots")

        # Character validation
        if not self._PATTERNS['valid_domain_chars'].match(domain_part):
            return ValidationResult(False, "DOMAIN_INVALID_CHARS", "Domain contains invalid characters")

        # Validate labels
        labels = domain_part.split('.')
        if len(labels) < 2:
            return ValidationResult(False, "INSUFFICIENT_LABELS", "Domain must have at least 2 labels")

        for i, label in enumerate(labels):
            label_result = self._validate_domain_label(label, is_tld=(i == len(labels) - 1))
            if not label_result.is_valid:
                return label_result

        return ValidationResult(True)

    def _validate_domain_label(self, label: str, is_tld: bool = False) -> ValidationResult:
        """Validate individual domain label."""
        if not label:
            return ValidationResult(False, "EMPTY_LABEL", "Domain label cannot be empty")

        if len(label) > self.MAX_LABEL_LENGTH:
            return ValidationResult(False, "LABEL_TOO_LONG", f"Domain label exceeds {self.MAX_LABEL_LENGTH} characters")

        # Boundary checks
        if label.startswith('-') or label.endswith('-'):
            return ValidationResult(False, "LABEL_BOUNDARY_HYPHEN", "Domain label cannot start/end with hyphen")

        # TLD-specific validation
        if is_tld:
            if len(label) < self.MIN_TLD_LENGTH:
                return ValidationResult(False, "TLD_TOO_SHORT", f"TLD must be at least {self.MIN_TLD_LENGTH} characters")

            if not self._PATTERNS['tld_pattern'].match(label):
                return ValidationResult(False, "INVALID_TLD", "TLD must contain only letters")
        else:
            # Regular label validation
            if not self._PATTERNS['valid_label_chars'].match(label):
                return ValidationResult(False, "LABEL_INVALID_CHARS", "Domain label contains invalid characters")

        return ValidationResult(True)

    def validate_batch(self, emails: List[str]) -> List[Tuple[str, ValidationResult]]:
        """
        Validate multiple emails efficiently.

        Args:
            emails: List of email addresses to validate

        Returns:
            List of (email, ValidationResult) tuples
        """
        return [(email, self.validate(email)) for email in emails]

    def get_cache_info(self) -> dict:
        """Get validation cache statistics."""
        cache_info = self.validate.cache_info()
        return {
            'hits': cache_info.hits,
            'misses': cache_info.misses,
            'maxsize': cache_info.maxsize,
            'currsize': cache_info.currsize,
            'hit_rate': cache_info.hits / (cache_info.hits + cache_info.misses) if (cache_info.hits + cache_info.misses) > 0 else 0
        }

    def clear_cache(self):
        """Clear the validation cache."""
        self.validate.cache_clear()


