          wait = Math.min(delay, maxWait);
        }
        startTimer(() => trailingEdge(performance.now()), wait);
      } else {
        // Timer already running – adjust for maxWait
        if (maxWait !== undefined) {
          const timeSinceLastInvoke = time - (lastInvokeTime ?? time);
          const remaining = Math.max(0, maxWait - timeSinceLastInvoke);
          const newWait = Math.min(delay, remaining);
          startTimer(() => trailingEdge(performance.now()), newWait);
        }
        // If no maxWait, just let the existing timer run – no reset needed.
      }
    } else {
      startTimer(() => trailingEdge(performance.now()), delay);
    }

    return result; // for leading calls, returns immediate result
  };

  // --- Utility methods ---

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
    lastCallTime = lastInvokeTime = null;
    lastArgs = lastThis = null;
    // Don't clear result – allow flush to return it
    return result;
  };
  debounced.clear = debounced.cancel;

  debounced.flush = () => {
    if (timer !== null && lastArgs) {
      return trailingEdge(performance.now());
    }
    // If no pending call, return last computed result (even if cancelled)
    return result;
  };

  debounced.isPending = () => timer !== null;

  /**
   * Returns a Promise that resolves with the result of the *next* actual invocation.
   * If no call is pending, returns a resolved promise with the last result (or undefined).
   */
  debounced.pending = () => {
    if (timer !== null && lastArgs) {
      return new Promise((resolve) => { resolvePromise = resolve; });
    }
    return Promise.resolve(result);
  };

  return debounced;
}
```

### What changed and why

| Improvement | Rationale |
|-------------|-----------|
| **Initial timer respects `maxWait`** | Prevents the first timer from being longer than `maxWait` when `leading` is true. |
| **`flush()` returns last result even after cancellation** | More intuitive: `cancel()` stores the last result, `flush()` returns it if no pending call. |
| **`pending()` returns a Promise** | Enables `await debounced.pending()` – useful for tests or ensuring async completion. |
| **No unnecessary timer reset when `maxWait` is absent** | If `maxWait` is undefined and the call is too early (not invoking), we still need to reset the trailing timer. That's correct – no change. |
| **`cancel()` preserves `result`** | So that `flush()` after cancel returns the last computed value (consistent with Lodash). |

### Still not perfect? 😄

If you need:
- **Throttle‑like behaviour with `maxWait` only** (no trailing) – that's a different pattern.
- **Error‑safe debounce** (catch errors in `invokeFn` and reject the pending promise) – easy to add.
- **Microtask debounce** (use `Promise.resolve().then(...)` instead of `setTimeout`) – for DOM update batching.

But for 99% of use cases, this version is production‑ready and handles the subtle edge cases that plague naïve implementations.

