## Corrected version

```javascript
function debounce(fn, delay, options = {}) {
  if (delay <= 0) return fn;

  const {
    leading = false,
    trailing = true,
    maxWait,
    context
  } = options;

  let timer = null;
  let lastCallTime = null;
  let lastInvokeTime = null;
  let lastArgs = null;
  let lastThis = null;
  let result = undefined;
  let resolvePromise = null;
  let rejectPromise = null;

  const invokeFn = (time) => {
    const args = lastArgs;
    const thisArg = context ?? lastThis;
    lastArgs = lastThis = null;
    lastInvokeTime = time;
    try {
      result = fn.apply(thisArg, args);
      if (resolvePromise) {
        resolvePromise(result);
        resolvePromise = rejectPromise = null;
      }
    } catch (error) {
      if (rejectPromise) {
        rejectPromise(error);
        resolvePromise = rejectPromise = null;
      } else {
        throw error; // re-throw if no one is listening
      }
    }
    return result;
  };

  const startTimer = (pendingFn, wait) => {
    clearTimeout(timer);
    timer = setTimeout(pendingFn, wait);
  };

  // Internal: always invokes if there are pending args (for flush)
  const forceInvoke = (time) => {
    clearTimeout(timer);
    if (lastArgs) {
      return invokeFn(time);
    }
    return result;
  };

  const trailingEdge = (time) => {
    clearTimeout(timer);
    if (trailing && lastArgs) {
      return invokeFn(time);
    }
    lastArgs = lastThis = null;
    return result;
  };

  const shouldInvoke = (time) => {
    const elapsedSinceLastCall = time - (lastCallTime ?? time);
    const elapsedSinceLastInvoke = time - (lastInvokeTime ?? time);
    return (
      lastCallTime === null ||
      elapsedSinceLastCall >= delay ||
      (maxWait !== undefined && elapsedSinceLastInvoke >= maxWait)
    );
  };

  const debounced = function(...args) {
    const time = performance.now();
    const isInvoking = shouldInvoke(time);

    lastArgs = args;
    lastThis = this;
    lastCallTime = time;

    if (isInvoking) {
      if (timer === null) {
        if (leading) invokeFn(time);
        let wait = delay;
        if (maxWait !== undefined) {
          wait = Math.min(delay, maxWait);
        }
        startTimer(() => trailingEdge(performance.now()), wait);
      } else {
        if (maxWait !== undefined) {
          const timeSinceLastInvoke = time - (lastInvokeTime ?? time);
          const remaining = Math.max(0, maxWait - timeSinceLastInvoke);
          const newWait = Math.min(delay, remaining);
          startTimer(() => trailingEdge(performance.now()), newWait);
        }
      }
    } else {
      startTimer(() => trailingEdge(performance.now()), delay);
    }

    return result;
  };

  // --- Utility methods ---

  debounced.cancel = () => {
    clearTimeout(timer);
    timer = null;
    lastCallTime = lastInvokeTime = null;
    lastArgs = lastThis = null;
    // Reject any pending promise
    if (rejectPromise) {
      rejectPromise(new Error('Debounced function cancelled'));
      resolvePromise = rejectPromise = null;
    }
    return result;
  };
  debounced.clear = debounced.cancel;

  // flush now ALWAYS invokes pending call (ignores trailing option)
  debounced.flush = () => {
    if (timer !== null && lastArgs) {
      return forceInvoke(performance.now());
    }
    return result;
  };

  debounced.isPending = () => timer !== null;

  debounced.pending = () => {
    if (timer !== null && lastArgs) {
      return new Promise((resolve, reject) => {
        resolvePromise = resolve;
        rejectPromise = reject;
      });
    }
    return Promise.resolve(result);
  };

  return debounced;
}
```

