```javascript
class AdvancedDebouncer {
  constructor(callback, delay, options = {}) {
    this.callback = callback;
    this.delay = delay;
    this.immediate = options.immediate || false;
    this.maxWait = options.maxWait || null;
    this.onInvoke = options.onInvoke || null; // Hook before execution
    this.onCancel = options.onCancel || null; // Hook on cancellation

    this.timeoutId = null;
    this.maxTimeoutId = null;
    this.lastArgs = null;
    this.lastThis = null;
    this.lastCallTime = null;
    this.result = null;
    this.invocationCount = 0;
    this.cancelCount = 0;

    // Bind methods
    this.debounced = this.debounced.bind(this);
    this.cancel = this.cancel.bind(this);
    this.flush = this.flush.bind(this);
  }

  debounced(...args) {
    this.invocationCount++;
    this.lastArgs = args;
    this.lastThis = this;

    const currentTime = performance.now();
    if (!this.lastCallTime) this.lastCallTime = currentTime;

    const callNow = this.immediate && !this.timeoutId;
    const timeSinceLastCall = currentTime - this.lastCallTime;

    this._clearTimers();

    // MaxWait enforcement
    if (this.maxWait && timeSinceLastCall >= this.maxWait) {
      return this._execute();
    }

    // Set debounce timer
    this.timeoutId = setTimeout(() => {
      this._clearTimers();
      if (!this.immediate) {
        this._execute();
      }
    }, this.delay);

    // Set maxWait timer
    if (this.maxWait && !this.maxTimeoutId) {
      const remainingMaxWait = this.maxWait - timeSinceLastCall;
      this.maxTimeoutId = setTimeout(() => {
        this._execute();
      }, remainingMaxWait);
    }

    if (callNow) {
      return this._execute();
    }

    return this.result;
  }

  _execute() {
    this.onInvoke?.(this.getStats());
    this._clearTimers();
    this.result = this.callback.apply(this.lastThis, this.lastArgs);
    this.lastCallTime = performance.now();
    return this.result;
  }

  _clearTimers() {
    clearTimeout(this.timeoutId);
    clearTimeout(this.maxTimeoutId);
    this.timeoutId = null;
    this.maxTimeoutId = null;
  }

  cancel() {
    this.cancelCount++;
    this.onCancel?.(this.getStats());
    this._clearTimers();
    this.lastCallTime = null;
    this.lastArgs = null;
    this.lastThis = null;
  }

  flush() {
    if (this.pending() && this.lastArgs) {
      return this._execute();
    }
    return this.result;
  }

  pending() {
    return this.timeoutId != null || this.maxTimeoutId != null;
  }

  getStats() {
    return {
      invocationCount: this.invocationCount,
      cancelCount: this.cancelCount,
      pending: this.pending(),
      lastCallTime: this.lastCallTime,
      hasResult: this.result !== null
    };
  }

  updateDelay(newDelay) {
    this.delay = newDelay;
    // Restart timer with new delay if pending
    if (this.pending()) {
      this.cancel();
      this.debounced(...(this.lastArgs || []));
    }
  }
}

