    return {
      invocationCount: this.state.invocationCount,
      avgExecutionTime: this.state.avgExecutionTime,
      adaptiveMultiplier: this.adaptiveMultiplier,
      currentDelay: this._getAdaptiveDelay(),
      queueSize: this.state.queue.length,
