```javascript
class WorkerDebouncer extends ReactiveDebouncer {
  constructor(callback, delay, options = {}) {
    super(callback, delay, options);

    if (options.useWorker && typeof Worker !== 'undefined') {
      this.worker = this._createWorker();
      this.workerCallbacks = new Map();
    }
  }

  _createWorker() {
    const workerScript = `
      let timeoutId = null;

      self.onmessage = function(e) {
        const { id, delay, args } = e.data;

        clearTimeout(timeoutId);

        timeoutId = setTimeout(() => {
          self.postMessage({ id, args, completed: true });
        }, delay);
      };
    `;

    const blob = new Blob([workerScript], { type: 'application/javascript' });
    const worker = new Worker(URL.createObjectURL(blob));

    worker.onmessage = (e) => {
      const { id, args } = e.data;
      const callback = this.workerCallbacks.get(id);
      if (callback) {
        this.workerCallbacks.delete(id);
        callback(args);
      }
    };

    return worker;
  }

  debounceWithWorker(...args) {
    if (!this.worker) return this.debounced(...args);

    return new Promise((resolve) => {
      const id = crypto.randomUUID();

      this.workerCallbacks.set(id, (debouncedArgs) => {
        const result = this.callback.apply(this, debouncedArgs);
        resolve(result);
      });

      this.worker.postMessage({ id, delay: this.delay, args });
    });
  }

  destroy() {
    if (this.worker) {
      this.worker.terminate();
      URL.revokeObjectURL(this.worker);
    }
    this.cancel();
  }
}
