  let timerId = null;
  let lastArgs = null;
  let lastThis = null;

  // Store the result of the callback for cases where we might need it
  let result;

  const debounced = function(...args) {
    lastArgs = args;
    lastThis = this;

    const shouldCallNow = immediate && !timerId;

    // Clear existing timer
    if (timerId) {
      clearTimeout(timerId);
    }

    // Set new timer
    timerId = setTimeout(() => {
      timerId = null;

      // Only call the callback on trailing edge (non-immediate)
      if (!immediate && lastArgs) {
        result = callback.apply(lastThis, lastArgs);
        lastArgs = lastThis = null;
      }
    }, delay);

    // Call immediately on leading edge
    if (shouldCallNow) {
      result = callback.apply(lastThis, lastArgs);
      lastArgs = lastThis = null;
    }

    return result;
  };

