   * Immediately invoke the pending callback if one exists
   * @returns {*} The result of the callback, or undefined if none pending
   */
  debounced.flush = function() {
    if (!timerId || !lastArgs) return undefined;

    const args = lastArgs;
    const context = lastThis;

    // Cancel the timer since we're executing now
    debounced.cancel();

    return callback.apply(context, args);
