        __slots__ = ['key', 'value', 'prev', 'next', 'expires_at', '_pool_ref']

        def __init__(self, key: Any = None, value: Any = None, expires_at: Optional[float] = None):
            self.key = key
            self.value = value
            self.prev: Optional['LRUCache._Node'] = None
            self.next: Optional['LRUCache._Node'] = None
            self.expires_at = expires_at
            self._pool_ref: Optional[WeakSet] = None

        def reset(self, key: Any = None, value: Any = None, expires_at: Optional[float] = None):
            """Reset node for reuse from pool."""
            self.key = key
            self.value = value
            self.prev = None
            self.next = None
            self.expires_at = expires_at
            return self

        def is_expired(self, current_time: float) -> bool:
            """Check if node has expired."""
            return self.expires_at is not None and current_time > self.expires_at

    class _Stats:
