        __slots__ = ['hits', 'misses', 'evictions', 'expirations', 'lock']

        def __init__(self):
            self.hits = 0
            self.misses = 0
            self.evictions = 0
            self.expirations = 0
            self.lock = threading.RLock()

        def record_hit(self):
            # Try lock-free increment first (CPython GIL helps here)
            self.hits += 1

        def record_miss(self):
            self.misses += 1

        def record_eviction(self):
            with self.lock:
                self.evictions += 1

        def record_expiration(self):
            with self.lock:
                self.expirations += 1

        def snapshot(self) -> dict:
            with self.lock:
                total = self.hits + self.misses
                return {
                    'hits': self.hits,
                    'misses': self.misses,
                    'evictions': self.evictions,
                    'expirations': self.expirations,
                    'hit_rate': (self.hits / total * 100) if total > 0 else 0.0
                }

    def __init__(
        self,
        capacity: int,
        ttl: Optional[float] = None,
        thread_safe: bool = True,
        node_pool_size: int = 0
    ):
        """
        Initialize advanced LRU cache.

        Args:
            capacity: Maximum number of items
            ttl: Time-to-live in seconds (None = no expiration)
            thread_safe: Enable thread safety (slight overhead)
            node_pool_size: Pre-allocate nodes for better performance
        """
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError(f"Capacity must be positive integer, got {capacity}")

        self._capacity = capacity
        self._cache: dict[K, LRUCache._Node] = {}
        self._ttl = ttl
        self._frozen = False
        self._stats = self._Stats()
        self._callbacks = {
            'on_hit': [],
            'on_miss': [],
            'on_evict': [],
            'on_expire': []
        }

        # Thread safety
        self._lock = threading.RLock() if thread_safe else None

        # Initialize linked list
        self._head = self._Node()
        self._tail = self._Node()
        self._head.next = self._tail
        self._tail.prev = self._head

        # Node pool for reduced GC pressure
        self._node_pool: list[LRUCache._Node] = []
        if node_pool_size > 0:
            self._node_pool = [self._Node() for _ in range(node_pool_size)]

    def _get_node(self, key: K, value: V, expires_at: Optional[float] = None) -> _Node:
        """Get node from pool or create new one."""
        if self._node_pool:
            node = self._node_pool.pop()
            return node.reset(key, value, expires_at)
        return self._Node(key, value, expires_at)

    def _return_node(self, node: _Node) -> None:
        """Return node to pool."""
        if len(self._node_pool) < self._capacity:  # Don't let pool grow too large
            node.reset()  # Clear references
            self._node_pool.append(node)

    def _current_time(self) -> float:
        """Get current time (can be overridden for testing)."""
        import time
        return time.time()

    def _is_expired(self, node: _Node) -> bool:
        """Check if node is expired."""
        return node.is_expired(self._current_time())

    def _unlink(self, node: _Node) -> None:
        """Remove node from linked list."""
        node.prev.next = node.next
        node.next.prev = node.prev

    def _link_after_head(self, node: _Node) -> None:
        """Insert node after head."""
        node.next = self._head.next
        node.prev = self._head
        self._head.next.prev = node
        self._head.next = node

    def _promote_to_head(self, node: _Node) -> None:
        """Move node to head position."""
        self._unlink(node)
        self._link_after_head(node)

    def _evict_expired(self) -> int:
        """Remove all expired nodes. Returns count of expired items."""
        if self._ttl is None:
            return 0

        current_time = self._current_time()
        expired_keys = []

        # Collect expired keys
        for key, node in self._cache.items():
            if node.is_expired(current_time):
                expired_keys.append(key)

        # Remove expired items
        for key in expired_keys:
            node = self._cache.pop(key, None)
            if node:
                self._unlink(node)
                self._return_node(node)
                self._stats.record_expiration()
                self._trigger_callback('on_expire', key, node.value)

        return len(expired_keys)

    def _evict_lru(self) -> Optional[_Node]:
        """Evict least recently used item."""
        if self._tail.prev is self._head:
            return None

        victim = self._tail.prev
        self._unlink(victim)
        del self._cache[victim.key]
        self._stats.record_eviction()
        self._trigger_callback('on_evict', victim.key, victim.value)
        return victim

    def _trigger_callback(self, event: str, key: K, value: V) -> None:
        """Trigger registered callbacks."""
        for callback in self._callbacks.get(event, []):
