                callback(key, value)
            except Exception:
                pass  # Don't let callback errors break cache

    def _with_lock(self, func, *args, **kwargs):
        """Execute function with lock if thread safety is enabled."""
        if self._lock:
            with self._lock:
                return func(*args, **kwargs)
