        self._with_lock(self._promote_to_head, node)
        self._stats.record_hit()
        self._trigger_callback('on_hit', key, node.value)
        return node.value

    def put(self, key: K, value: V, ttl: Optional[float] = None) -> None:
        """Put item with optional per-item TTL."""
        if self._frozen:
