        expires_at = None
        if ttl is not None or self._ttl is not None:
            expires_at = self._current_time() + (ttl or self._ttl)

        def _put_impl():
            # Clean expired items periodically
            if len(self._cache) > self._capacity * 0.8:  # Threshold to avoid too frequent cleanup
                self._evict_expired()

