        self._with_lock(_put_impl)

    def put_many(self, items: dict[K, V], ttl: Optional[float] = None) -> None:
        """Batch insert for better performance."""
        def _put_many_impl():
            for key, value in items.items():
                self.put(key, value, ttl)  # Reuse single-item logic

        self._with_lock(_put_many_impl)

    def get_many(self, keys: list[K], default: V = None) -> dict[K, V]:
        """Batch get for better performance."""
        result = {}
        for key in keys:
            result[key] = self.get(key, default)
        return result

    def peek(self, key: K, default: V = None) -> V:
        """Get without affecting LRU order or triggering callbacks."""
        node = self._cache.get(key)
        if node is None or self._is_expired(node):
