        return self._with_lock(_expire_impl)

    def freeze(self) -> None:
        """Freeze cache (make read-only)."""
        self._frozen = True

    def unfreeze(self) -> None:
        """Unfreeze cache."""
        self._frozen = False

    def add_callback(self, event: str, callback) -> None:
        """Add event callback. Events: on_hit, on_miss, on_evict, on_expire."""
        if event in self._callbacks:
