        self._cache: dict[K, CacheNode] = {}
        self._size = 0
        self._shutdown_event = threading.Event()

        # Metrics
        self._metrics = CacheMetrics() if config.enable_stats else None

        # Eviction policy
        self._eviction_policy = eviction_policy or LRUEvictionPolicy()

        # Initialize sentinels
        self._head = CacheNode(None, None)  # type: ignore
        self._tail = CacheNode(None, None)  # type: ignore
        self._head.next = self._tail
        self._tail.prev = self._head

        # Threading infrastructure
        self._locks = self._create_lock_infrastructure()

        # Background processing
        self._background_executor = ThreadPoolExecutor(
            max_workers=2, 
            thread_name_prefix="cache-bg"
        )

        # Advanced features
        self._circuit_breaker = CircuitBreaker()
        self._memory_manager = MemoryManager(config)
        self._persistence_manager = PersistenceManager(persistence_file) if persistence_file else None

        # Write buffer for batch operations
        self._write_buffer: list[Tuple[str, K, V, Optional[float]]] = []

        # Start background tasks
        self._start_background_tasks()

    def _create_lock_infrastructure(self) -> dict:
        """Create optimized locking infrastructure."""
        if not self._config.thread_safe:
            return {'main': _NoOpLock(), 'metrics': _NoOpLock()}

        return {
            'main': SegmentedRWLock(segments=16),  # Reduce contention
            'metrics': threading.Lock(),
            'write_buffer': threading.Lock()
        }

    def _start_background_tasks(self) -> None:
        """Start background maintenance tasks."""
        if self._config.background_cleanup_interval > 0:
            self._background_executor.submit(self._background_cleanup_loop)

        if self._persistence_manager:
            self._background_executor.submit(self._background_persistence_loop)

    def _background_cleanup_loop(self) -> None:
        """Background cleanup task."""
        while not self._shutdown_event.is_set():
            try:
                with suppress(Exception):
                    self._perform_maintenance()

                self._shutdown_event.wait(self._config.background_cleanup_interval)
            except Exception:
                continue  # Keep running despite errors

    def _background_persistence_loop(self) -> None:
        """Background persistence task."""
        if not self._persistence_manager:
            return

        while not self._shutdown_event.is_set():
            try:
                self._flush_write_buffer()
