class StatisticsEngine:
    """Advanced statistics calculation engine."""

    @staticmethod
    def calculate_numeric_stats(values: List[Union[int, float]], config: AnalysisConfig) -> Dict[str, Any]:
        if not values:
            return {}

        n = len(values)
        sorted_vals = sorted(values)

        # Basic statistics
        stats = {
            'count': n,
            'min': sorted_vals[0],
            'max': sorted_vals[-1],
            'sum': sum(values),
            'mean': sum(values) / n
        }

        # Percentiles
        def percentile(data, p):
            k = (len(data) - 1) * p / 100
            f = math.floor(k)
            c = math.ceil(k)
            if f == c:
                return data[int(k)]
            return data[int(f)] * (c - k) + data[int(c)] * (k - f)

        stats.update({
            'median': percentile(sorted_vals, 50),
            'q1': percentile(sorted_vals, 25),
            'q3': percentile(sorted_vals, 75),
            'p90': percentile(sorted_vals, 90),
            'p95': percentile(sorted_vals, 95),
            'p99': percentile(sorted_vals, 99)
        })

        # Variance and standard deviation
        variance = sum((x - stats['mean']) ** 2 for x in values) / n
        stats.update({
            'variance': variance,
            'std_dev': math.sqrt(variance),
            'range': stats['max'] - stats['min'],
            'iqr': stats['q3'] - stats['q1']
        })

        # Advanced statistics
        if stats['std_dev'] > 0:
            # Skewness and kurtosis
            normalized_values = [(x - stats['mean']) / stats['std_dev'] for x in values]
            stats['skewness'] = sum(x**3 for x in normalized_values) / n
            stats['kurtosis'] = sum(x**4 for x in normalized_values) / n - 3
        else:
            stats['skewness'] = 0
            stats['kurtosis'] = 0

        # Outlier detection
        if config.outlier_detection_method == 'iqr':
            iqr_multiplier = config.outlier_threshold
            lower_bound = stats['q1'] - iqr_multiplier * stats['iqr']
            upper_bound = stats['q3'] + iqr_multiplier * stats['iqr']
            outliers = [v for v in values if v < lower_bound or v > upper_bound]

            stats['outliers'] = {
                'method': 'IQR',
                'count': len(outliers),
                'percentage': len(outliers) / n * 100,
                'lower_bound': lower_bound,
                'upper_bound': upper_bound,
                'values': sorted(outliers)[:20]  # Show first 20
            }

        return stats

    @staticmethod
    def calculate_text_stats(values: List[str], config: AnalysisConfig) -> Dict[str, Any]:
        if not values:
            return {}

        # Basic counts
        lengths = [len(str(v)) for v in values]
        unique_values = list(set(values))
        value_counts = Counter(values)

        stats = {
            'count': len(values),
            'unique_count': len(unique_values),
            'uniqueness_ratio': len(unique_values) / len(values),
            'most_frequent': value_counts.most_common(10),
            'length_stats': {
                'min': min(lengths),
                'max': max(lengths),
                'mean': sum(lengths) / len(lengths),
                'median': sorted(lengths)[len(lengths)//2]
            }
        }

        # Pattern analysis
        patterns = {
            'emails': sum(1 for v in values if '@' in v and '.' in v),
            'urls': sum(1 for v in values if v.startswith(('http://', 'https://'))),
            'phone_numbers': sum(1 for v in values if re.match(r'[\d\s\-\(\)\+\.]{10,}', v)),
            'numeric_strings': sum(1 for v in values if v.isdigit()),
            'uppercase': sum(1 for v in values if v.isupper()),
            'lowercase': sum(1 for v in values if v.islower()),
            'mixed_case': sum(1 for v in values if not v.isupper() and not v.islower()),
        }
        stats['patterns'] = {k: v for k, v in patterns.items() if v > 0}

        return stats

class StreamingCSVAnalyzer:
    """Memory-efficient streaming CSV analyzer."""

    def __init__(self, config: AnalysisConfig):
        self.config = config
        self.detectors = self._initialize_detectors()
        self.reset()

    def _initialize_detectors(self) -> List[DataTypeDetector]:
        """Initialize and sort detectors by priority."""
        detectors = [
            NumericDetector(),
            DateTimeDetector(),
            BooleanDetector(),
            CategoricalDetector(),
            TextDetector()
        ]
        return sorted(detectors, key=lambda d: d.get_priority())

    def reset(self):
        """Reset analyzer state."""
        self.filename = ""
        self.headers = []
        self.row_count = 0
        self.column_profiles = []
        self.file_metadata = {}
        self.issues = []
        self.processing_stats = {}

    def analyze_file(self, filepath: Union[str, Path]) -> Dict[str, Any]:
        """Analyze CSV file with streaming approach for memory efficiency."""
        filepath = Path(filepath)
        self.reset()
        self.filename = filepath.name

        start_time = datetime.now()
        logger.info(f"Starting analysis of {filepath}")

        try:
            # File metadata
            self.file_metadata = {
                'name': filepath.name,
                'size_bytes': filepath.stat().st_size,
                'size_human': self._format_size(filepath.stat().st_size),
                'modified': datetime.fromtimestamp(filepath.stat().st_mtime).isoformat(),
                'analysis_timestamp': start_time.isoformat()
            }

            # Memory check for large files
            if self.file_metadata['size_bytes'] > self.config.max_file_size_mb * 1024 * 1024:
                logger.warning(f"Large file detected: {self.file_metadata['size_human']}")

            # Stream process the file
            encoding = self._detect_encoding(filepath)
            self.file_metadata['encoding'] = encoding

